function U.now()
return os.clock()
end
function U.json(ub)
local vb,wb=pcall(J.JSONEncode,J,ub)
return vb and wb or QWd[1802]
end
function U.unjson(xb)
local yb,zb=pcall(J.JSONDecode,J,xb)
return yb and zb or nil
end
function U.readJson(Ab)
local Bb,Cb=pcall(function()
return isfile(Ab)and readfile(Ab)or nil
end)
return Bb and Cb and U.unjson(Cb)or nil
end
function U.writeJson(Db,Eb)
pcall(function()
if not isfolder(N.FOLDER)then
makefolder(N.FOLDER)
end
end)
pcall(writefile,Db,U.json(Eb))
end
function U.fmt(Fb)
Fb=tonumber(Fb)or 0
if Fb>=1e6 then
return string.format(QWd[1803],Fb/1e6)
end
if Fb>=1e4 then
return string.format(QWd[1804],Fb/1e3)
end
return tostring(math.floor(Fb+0.5))
end
function U.clamp(Gb,Hb,Ib)
return math.max(Hb,math.min(Ib,Gb))
end
function U.count(Jb)
local Kb=0
for Lb in pairs(Jb or{})do
Kb=Kb+1
end
return Kb
end
function U.list(Mb)
if type(Mb)~=QWd[1805]then
return{}
end
if#Mb>0 then
return Mb
end
local Nb={}
for Ob in pairs(Mb)do
table.insert(Nb,Ob)
end
table.sort(Nb,function(Pb,Qb)
return(tonumber(Pb)or 0)<(tonumber(Qb)or 0)
end)
local Rb={}
for Sb,Tb in ipairs(Nb)do
table.insert(Rb,Mb[Tb])
end
return Rb
end
function U.flat(Ub)
return Vector3 .new(Ub.X,0,Ub.Z)
end
function U.plain(Vb,Wb)
local Xb=type(Vb)
if Xb==QWd[1806]or Xb==QWd[715]or Xb==QWd[1807]then
return Vb
end
if Xb~=QWd[1805]or(Wb or 0)>6 then
return nil
end
local Yb={}
for Zb,_b in pairs(Vb)do
if type(Zb)==QWd[1806]or type(Zb)==QWd[715]then
Yb[Zb]=U.plain(_b,(Wb or 0)+1)
end
end
return Yb
end
function F.log(cc,dc,ec)
if cc>(O.logLevel or 1)then
return
end
local fc=string.format(QWd[1808],os.date(QWd[1809]),dc,tostring(ec))
table.insert(R.lines,fc)
if#R.lines>250 then
table.remove(R.lines,1)
end
table.insert(R.pending,fc)
local gc=tostring(ec):lower()
if gc:find(QWd[1810])or gc:find(QWd[1811])or gc:find(QWd[1812])or dc==QWd[1813]then
R.problems=R.problems or{}
table.insert(R.problems,fc)
if#R.problems>30 then
table.remove(R.problems,1)
end
end
if O.logConsole then
print(QWd[1814]..fc)
end
end
function F.status(hc,jc)
Q[hc]=jc
F.statusAt=F.statusAt or{}
F.statusAt[hc]=os.time()
end
function F.flush()
if#R.pending==0 then
return
end
local kc=table.concat(R.pending,QWd[1815])..QWd[1815]
table.clear(R.pending)
pcall(function()
if not isfolder(N.FOLDER)then
makefolder(N.FOLDER)
end
if appendfile and isfile(N.LOGFILE)then
appendfile(N.LOGFILE,kc)
else
writefile(N.LOGFILE,kc)
end
end)
end
task.spawn(function()
while F.alive do
task.wait(3)
F.flush()
end
end)
do
local lc=U.readJson(N.SETTINGS)or{}
if lc.shareChosen~=true then
lc.shareStats=nil
end
if lc.autoTeamChosen~=true then
lc.autoTeam=nil
end
for mc,nc in pairs(N.DEFAULTS)do
if lc[mc]~=nil and type(lc[mc])==type(nc)then
O[mc]=lc[mc]
else
O[mc]=nc
end
end
O.seenVersion=type(lc.seenVersion)==QWd[715]and lc.seenVersion or nil
if lc.griffinWatch==true and lc.snipeUnit==nil then
O.snipeOn,O.snipeUnit=true,QWd[887]
end
if O.pickPortal==QWd[732]then
O.portals,O.pickPortal=false,QWd[730]
end
if O.huntCards==QWd[1816]then
O.huntCards=QWd[1817]
end
O.cfgv=1
if not O.simpleGui then
O.simpleGui=true
if not O.play then
O.master=false
