local il=false
local jl=U.flat(gl.pos)
for kl,ll in ipairs(al)do
if(jl-U.flat(ll.pos)).Magnitude<=ll.range+3 then
il=true
break
end
end
local ml=hk.foe[hl]
if il or ml then
local nl=hl:FindFirstChildOfClass(QWd[2178])
local ol=math.max(1,(nl and nl.MaxHealth)or gl.hp or 1)
if not ml then
ml={hp=gl.hp,on={},met={},speed0=nl and nl.WalkSpeed or nil,boss=gl.boss or nil}
hk.foe[hl]=ml
hk.nearN=hk.nearN+1
end
el=el+1
if el<=ob.ENEMY_MAX then
local pl=hl:FindFirstChild(QWd[1867])
local ql={}
for rl,sl in ipairs(pl and pl:GetChildren()or{})do
if sl.Name:sub(1,8)==QWd[2179]and sl:IsA(QWd[2174])and tonumber(sl.Value)then
ql[sl.Name]=tonumber(sl.Value)/ol
end
end
local tl=((ml.hp or gl.hp)-gl.hp)/ol
if tl>=0.08 and#hk.steps<300 then
local ul
for vl,wl in pairs(ml.met)do
if wl>0.02 and(ql[vl]or 0)<wl*0.3 then
ul=ul or{}
ul[vl]=wl
end
end
table.insert(hk.steps,{t=kk,before=(ml.hp or gl.hp)/ol,drop=tl,boss=gl.boss or nil,reset=ul})
end
for xl,yl in pairs(ql)do
local zl=hk.meters[xl]or{max=0,n=0}
zl.max,zl.n=math.max(zl.max,yl),zl.n+1
hk.meters[xl]=zl
end
ml.met=ql
local Al=hl:FindFirstChild(QWd[2173])
local Bl={}
for Cl,Dl in ipairs(Al and Al:GetChildren()or{})do
local El=(Dl:IsA(QWd[2174])and tonumber(Dl.Value))or 1
if El~=0 then
Bl[Dl.Name]=El
end
end
for Fl,Gl in pairs(Bl)do
local Hl=hk.foeBuffs[Fl]
if not Hl then
Hl={first=kk,last=kk,n=0,foes=0,near=0,boss=0,max=Gl,durs={},sp=0,spN=0,onsets={}}
hk.foeBuffs[Fl]=Hl
end
Hl.n,Hl.last,Hl.max=Hl.n+1,kk,math.max(Hl.max,Gl)
if il then
Hl.near=Hl.near+1
end
if ml.boss then
Hl.boss=Hl.boss+1
end
if not ml.on[Fl]then
ml.on[Fl]=kk
Hl.foes=Hl.foes+1
if#Hl.onsets<200 then
table.insert(Hl.onsets,kk)
end
end
if nl and(ml.speed0 or 0)>0 then
Hl.sp,Hl.spN=Hl.sp+nl.WalkSpeed/ml.speed0,Hl.spN+1
end
end
for Il,Jl in pairs(ml.on)do
if not Bl[Il]then
local Kl=hk.foeBuffs[Il]
if Kl and#Kl.durs<80 then
table.insert(Kl.durs,kk-Jl)
end
ml.on[Il]=nil
end
end
end
ml.hp=gl.hp
ml.frac=(gl.hp or 0)/ol
end
end
end
for Ll,Ml in pairs(hk.foe)do
if not dl[Ll]then
if#hk.deaths<600 and Ml.frac then
table.insert(hk.deaths,{frac=Ml.frac,boss=Ml.boss})
end
hk.foe[Ll]=nil
end
end
for Nl,Ol in pairs(bb.helperDealt or{})do
if Ol.owner and hk.ids[Ol.owner]then
local Pl=hk.sumOf[Nl]
if not Pl then
local Ql=0
for Rl,Sl in pairs(hk.copies)do
if Sl.id==Ol.owner and not Sl.gone then
Ql=Ql+(Sl.tk or 0)
end
end
Pl={owner=Ol.owner,id=Ol.id,born=kk,tk=Ql}
hk.sumOf[Nl]=Pl
if#hk.summons<200 then
table.insert(hk.summons,Pl)
end
end
if Nl.Parent then
Pl.last=kk
elseif not Pl.died then
Pl.died=kk
end
end
end
for Tl in pairs(hk.ids)do
local Ul=bb.casts and tonumber(bb.casts[Tl])or 0
if Ul>(hk.castN[Tl]or 0)then
hk.castN[Tl]=Ul
if#hk.casts<100 then
table.insert(hk.casts,{t=kk,id=Tl})
end
end
end
end
function ob.evidence(Vl,Wl,Xl)
local Yl=type(Xl.nums)==QWd[1805]and Xl.nums or{}
local Zl=Vl.firstPlaced[Wl]
if not Zl then
return{why=QWd[2180]}
end
local am={}
for bm,cm in ipairs(Xl.buffs or{})do
am[cm]=true
end
local function dm(em)
if#em==0 then
return nil
end
table.sort(em)
return em[math.ceil(#em/2)]
end
if Xl.family==QWd[1978]then
if(Vl.sales or 0)==0 then
return{why=QWd[2181]}
end
local fm,hm
for im in pairs(Vl.own)do
local jm,km,lm,nm,om=0,0,0,0,0
for qm,rm in pairs(Vl.copies)do
local um=rm.buff[im]or 0
if(rm.sold or 0)>0 then
if rm.id~=Wl then
nm=nm+1
end
if um>0 then
if rm.id==Wl then
jm=jm+1
else
lm=lm+1
end
om=math.max(om,um)
end
elseif um>0 then
km=km+1
end
end
if jm>0 and km==0 and(not hm or jm>hm)then
fm,hm={name=im,other=lm,otherAfter=nm,top=om},jm
end
end
if not fm then
return{why=QWd[2182]}
end
local vm=(fm.other>0 and QWd[737])or(fm.otherAfter>0 and QWd[2183])or QWd[2184]
return{seen=true,buff=fm.name,who=vm,nums={stacks=(Vl.sales>1 and fm.top>1)or nil,sales=Vl.sales},why=string.format(QWd[2185],hm,fm.name,vm==QWd[2183]and QWd[2186]or QWd[729])}
end
local wm=Xl.trigger and tostring(Xl.trigger):find(QWd[2187],1,true)~=nil
local xm=0
for ym,zm in ipairs(Vl.casts)do
if zm.id==Wl then
xm=xm+1
end
end
if wm and xm==0 and(Xl.family==QWd[1979]or Xl.family==QWd[1976])then
return{why=QWd[2188]}
end
if Xl.family==QWd[1979]then
local Am,Bm,Cm
for Dm,Em in pairs(Vl.own)do
if Em.first>=Zl-1 and(am[Dm]or Em.first<=Zl+5 or wm)and(not wm or ob.nearCast(Vl,Wl,Em.starts)>0)then
local Fm=0
for Gm,Hm in pairs(Em.by)do
if Gm~=Wl then
Fm=Fm+Hm
end
end
if Fm>0 and(not Am or(am[Dm]and not Cm)or((am[Dm]or false)==(Cm or false)and Fm>Bm))then
Am,Bm,Cm=Dm,Fm,am[Dm]
end
end
end
if not Am then
return{why=QWd[2189]}
end
return{seen=true,buff=Am,why=string.format(QWd[2190],Am)}
end
if Xl.family==QWd[1976]then
local Im,Jm
for Km,Lm in pairs(Vl.foeBuffs)do
if Lm.first>=Zl-1 and Lm.near>0 and(am[Km]or Lm.near>=0.5*Lm.n)and(not wm or ob.nearCast(Vl,Wl,Lm.onsets)>0)then
local Mm=Lm.near+(am[Km]and 1e6 or 0)+(wm and ob.nearCast(Vl,Wl,Lm.onsets)*1000 or 0)
if not Jm or Mm>Jm then
Im,Jm=Km,Mm
end
end
end
if not Im then
return{why=QWd[2191]}
end
local Nm=Vl.foeBuffs[Im]
local Om={}
if#Nm.durs>=3 then
Om.secsSeen=math.floor(dm(Nm.durs)*10+0.5)/10
elseif Nm.foes>=5 then
Om.keepSeen=true
end
if Nm.spN>=5 then
local Pm=Nm.sp/Nm.spN
if Pm<0.97 then
Om.slowSeen=math.floor((1-Pm)*100+0.5)/100
end
end
if Yl.chance and(Vl.nearN or 0)>0 then
Om.chanceSeen=math.floor(math.min(1,Nm.foes/Vl.nearN)*100+0.5)/100
end
Om.bossToo=Nm.boss>0 or nil
return{seen=true,buff=Im,nums=Om,why=string.format(QWd[2192],Nm.foes,Im)}
end
if Xl.family==QWd[2035]then
local Qm=(tonumber(Yl.below)or 0.25)+0.02
local Rm,Sm=0,0
for Tm,Um in ipairs(Vl.deaths)do
if not Um.boss then
Sm=Sm+1
if Um.frac>0.04 and Um.frac<=Qm then
Rm=Rm+1
end
end
end
if Sm<10 then
return{why=QWd[2193]}
end
local Vm=Rm/Sm
if Vm<0.3 then
return{why=string.format(QWd[2194],math.floor(Vm*100))}
end
return{seen=true,nums={shareSeen=math.floor(Vm*100+0.5)/100},why=string.format(QWd[2195],Rm,Sm,math.floor(Qm*100))}
end
if Xl.family==QWd[1890]then
local Wm={}
for Xm,Ym in ipairs(Vl.summons)do
if Ym.owner==Wl then
table.insert(Wm,Ym)
end
end
if#Wm<2 then
return{why=QWd[2196]}
end
table.sort(Wm,function(Zm,_m)
return Zm.born<_m.born
end)
local an,bn,cn={},{},{}
for dn=2,#Wm do
local en=(Wm[dn].tk or 0)-(Wm[dn-1].tk or 0)
if en>0 then
table.insert(an,en)
end
end
for gn,hn in ipairs(Wm)do
if hn.died then
table.insert(bn,hn.died-hn.born)
end
table.insert(cn,{hn.born,1})
table.insert(cn,{hn.died or hn.last or hn.born,-1})
end
table.sort(cn,function(jn,kn)
return jn[1]<kn[1]
end)
local ln,mn=0,0
for nn,pn in ipairs(cn)do
ln=ln+pn[2]
mn=math.max(mn,ln)
end
local qn=dm(bn)
return{seen=true,nums={everySeen=dm(an),lifeSeen=qn and math.floor(qn+0.5)or nil,capSeen=mn,made= #Wm},why=string.format(QWd[2197],#Wm)}
end
if Xl.family==QWd[1980]then
local rn,un
for vn,wn in pairs(Vl.own)do
if(wn.by[Wl]or 0)>0 and wn.first>=Zl-1 and(not rn or(am[vn]and not am[rn]))then
rn,un=vn,wn
end
end
local xn
for yn,zn in ipairs(Vl.transforms)do
if zn.from==Wl then
xn=zn.to
end
end
if not rn then
local An,Bn,Cn
for Dn,En in pairs(Vl.copies)do
if En.id==Wl or(xn and En.id==xn)then
for Fn,Gn in pairs(En.stat or{})do
if Gn.hi>Gn.lo and(not An or(Gn.hi-Gn.lo)>(Cn-Bn))then
An,Bn,Cn=Fn,Gn.lo,Gn.hi
end
end
end
end
if not An then
return{why=QWd[2198]}
end
return{seen=true,nums={stat=An,loSeen=Bn,hiSeen=Cn,transformTo=xn},why=string.format(QWd[2199],An,tostring(Bn),tostring(Cn))}
end
return{seen=true,buff=rn,nums={maxSeen=un.max,steps= #un.vals,transformTo=xn},why=string.format(QWd[2200],rn,tostring(un.max))}
end
if Xl.family==QWd[1977]then
local Hn,In,Jn={},{},nil
for Kn,Ln in ipairs(Vl.steps)do
for Mn,Nn in pairs(Ln.reset or{})do
table.insert(Hn,Nn)
table.insert(In,Ln.drop)
Jn=Jn or Mn
end
end
if#Hn<3 then
return{why=QWd[2201]}
end
return{seen=true,nums={atSeen=dm(Hn),hitSeen=dm(In),meter=Jn},why=string.format(QWd[2202],#Hn)}
end
if Xl.family==QWd[2078]then
return{why=QWd[2203]}
end
return{why=QWd[2204]}
end
function ob.learn(On)
local Pn={}
for Qn in pairs(On.ids or{})do
local Rn,Sn=pcall(ob.guess,Qn)
for Tn,Un in ipairs(Rn and type(Sn)==QWd[1805]and Sn or{})do
if Un.playable and not Un.hand then
local Vn,Wn=pcall(ob.evidence,On,Qn,Un)
if Vn and type(Wn)==QWd[1805]and Wn.seen then
local Xn=type(P.pasBook[Qn])==QWd[1805]and P.pasBook[Qn]or{}
local Yn=type(Xn[Un.pid])==QWd[1805]and Xn[Un.pid]or nil
local Zn={}
for ao,bo in pairs(Un.nums or{})do
Zn[ao]=bo
end
for co,eo in pairs(Wn.nums or{})do
Zn[co]=eo
end
local fo=Yn~=nil and Yn.family==Un.family and(Yn.buff==nil or Wn.buff==nil or Yn.buff==Wn.buff)
Xn[Un.pid]={family=Un.family,name=Un.name,nums=Zn,buff=Wn.buff or(Yn and Yn.buff),who=Wn.who or Un.who,trigger=Un.trigger,keyword=Un.keyword,sure=(fo and(tonumber(Yn.runs)or 0)>=1)and QWd[2154]or QWd[2205],runs=(fo and(tonumber(Yn.runs)or 0)or 0)+1,at=os.time(),why=Wn.why}
P.pasBook[Qn]=Xn
table.insert(Pn,{id=Qn,g=Un,e=Xn[Un.pid]})
elseif Vn and type(Wn)==QWd[1805]then
table.insert(Pn,{id=Qn,g=Un,miss=Wn.why})
else
table.insert(Pn,{id=Qn,g=Un,miss=QWd[2206]..tostring(Wn)})
end
end
end
end
ob._model={}
return Pn
end
function ob.unexplained(ho,io)
if not(ho and ho.firstPlaced and ho.firstPlaced[io])then
return nil
end
local jo={}
for ko,mo in ipairs(ho.learned or{})do
if mo.id==io and mo.e and mo.e.buff then
jo[mo.e.buff]=true
end
end
local oo={}
for po,qo in pairs(ho.own)do
if(qo.by[io]or 0)>0 and not jo[po]then
table.insert(oo,{w=QWd[2207],b=po,n=qo.by[io],max=qo.max})
end
end
for ro,so in pairs(ho.foeBuffs)do
if so.near>0 and so.first>=ho.firstPlaced[io]-1 and not jo[ro]then
table.insert(oo,{w=QWd[2208],b=ro,n=so.foes,max=so.max})
end
end
table.sort(oo,function(uo,vo)
return uo.n>vo.n
end)
local wo={}
for xo=1,math.min(6,#oo)do
wo[xo]=oo[xo]
end
return#wo>0 and wo or nil
end
function ob.finish()
local yo=bb.pas
if not(yo and(yo.n or 0)>0)then
return
end
local zo=ob.learn(yo)
yo.learned=zo
local Ao=P.trial and P.trial.study
if Ao and bb.trialId then
P.pasBook[bb.trialId]=type(P.pasBook[bb.trialId])==QWd[1805]and P.pasBook[bb.trialId]or{}
P.pasBook[bb.trialId]._tries=(tonumber(P.pasBook[bb.trialId]._tries)or 0)+1
end
for Bo,Co in ipairs(zo)do
if Co.e then
F.log(1,QWd[2165],string.format(QWd[2209],V.name(Co.id),Co.g.name,ob.words(ob.withBook(Co.id,Co.g)),ob.SURE_WORDS[Co.e.sure]or tostring(Co.e.sure),tostring(Co.e.why)))
elseif Ao and Co.id==bb.trialId then
F.log(1,QWd[2165],string.format(QWd[2210],V.name(Co.id),Co.g.name,tostring(Co.miss)))
end
end
F.saveSoon()
