for Xy,Yy in pairs(Vy.kinds)do
Wy=Wy*(1+bb.rogueShare(Xy)*Yy)
end
if Vy.ice>0 then
local Zy=bb.rogueShare(QWd[1940])
Wy=Wy*(Zy+(1-Zy)/(1-Vy.ice+Vy.ice/fb.modFactor(QWd[2311])))
end
if Vy.fly>0 then
Wy=Wy*(1-Vy.fly*0.5)
end
if Vy.noCC then
Wy=Wy*0.95
end
if Vy.shroud then
Wy=Wy*0.9
end
if Vy.zap then
Wy=Wy*0.85
end
return Wy/kb.weatherK(Uy)
end
