qz=U.clamp(qz,kb.WEATHER_K_MIN,kb.WEATHER_K_MAX)
bb.wkWas={w=tostring(bz),old=mz}
P.hunt.wk[tostring(bz)]={k=qz,n=(type(mz)==QWd[1805]and tonumber(mz.n)or 0)+1,at=os.time()}
F.log(1,QWd[2312],string.format(QWd[2313],tostring(bz),lz,tostring(bz),qz,oz,P.hunt.wk[tostring(bz)].n))
