function kb.cardGems(rz,sz)
local tz=0
local uz=kb.pearlsFrom(sz+1,50)
for vz,wz in pairs(type(rz.effects)==QWd[1805]and rz.effects or{})do
if type(wz)==QWd[1805]then
local xz=tonumber(wz.amount)or 0
if wz.type==QWd[2314]then
tz=tz+math.abs(xz)*uz*O.pearlValue
elseif wz.type==QWd[2315]then
local yz,zz=pcall(W.rewardValue,wz.reward)
if yz then
tz=tz+(tonumber(zz)or 0)
end
elseif wz.type==QWd[2316]then
tz=tz+xz*kb.STARFALL_GEMS
elseif wz.type==QWd[2317]then
tz=tz+xz*100
end
end
end
if rz.option_type==QWd[2318]then
tz=tz+kb.HARD_GEMS
end
if rz.weather then
local Az=rz.weather~=kb.weatherNow()
if Az and rz.weather==QWd[2264]then
tz=tz+kb.starfallRemnants(50-(tonumber(sz)or 0))*W.remnantGems(QWd[2268])
end
local Bz=kb.board()
if Az and Bz and rz.weather~=QWd[2270]and not Bz.weathers[rz.weather]then
tz=tz+(1000+5000*O.pearlValue+50*W.remnantGems(QWd[2268]))/kb.WEATHERS
end
end
return tz
end
