ab.SNIPE_KEEP={gems=QWd[3042],SummerPearls=QWd[3043],GemsLegacy=QWd[3044]}
ab.SNIPE_ALSO={griffith={QWd[880]}}
function ab.snipeForms(Jdb)
local Kdb,Ldb={},{}
while Jdb and N.Units[Jdb]and not Ldb[Jdb]do
Ldb[Jdb]=true
table.insert(Kdb,Jdb)
