Jdb=type(Mdb)==QWd[1805]and Mdb.evolve_unit or nil
end
for Ndb,Odb in ipairs(ab.SNIPE_ALSO[Kdb[1]]or{})do
table.insert(Kdb,Odb)
end
return Kdb
end
function ab.snipeHas(Pdb)
Pdb=Pdb or O.snipeUnit
if not Pdb or Pdb==QWd[729]then
return false
end
for Qdb,Rdb in ipairs(ab.snipeForms(Pdb))do
