return nil
end
Tdb.cur=(Udb.item_cost and Udb.item_cost.item_id)or(Udb.resource_cost and Udb.resource_cost.id)or QWd[1868]
Tdb.keep=tonumber(O[ab.SNIPE_KEEP[Tdb.cur]or Tdb.floor])or 0
Tdb.label=ab.BANNER_NAME[Sdb]or Sdb
