function ab.snipeRate()
local _db
for aeb,beb in pairs(N.Banners or{})do
if type(beb)==QWd[1805]and beb.active and not beb._does_not_rotate and tonumber(beb.HATCH_REFRESH_RATE)then
_db=math.min(_db or math.huge,tonumber(beb.HATCH_REFRESH_RATE))
end
end
return _db or 14400
end
function ab.snipeTurnAfter(ceb)
local deb=ab.snipeRate()
local eeb=P.snipe.clock
local feb=(eeb and tonumber(eeb.next)or 0)%deb
