local Vhb=Uhb[#Uhb]
if Vhb and not W.done(Nhb,Vhb.id,QWd[2222])then
Ohb,Phb,Qhb=Shb,Uhb[1],Vhb
break
end
end
end
if not(Ohb and Mhb[Ohb]and Phb and Qhb)then
