local Yhb=tostring(Xhb and Xhb.name or Ohb)
local Zhb={key=QWd[2459]..Qhb.id..QWd[2563],kind=QWd[1843],first=true,level=Qhb.id,diff=QWd[2222],label=W.levelName(Qhb.id)..QWd[2564]}
