if W.open(Qhb.id)then
hib=true
break
end
end
local iib=F.gameSaid(eib)
P.worldSkip[Ohb]={at=os.time(),done=hib or nil,last=Qhb.id,said=iib and tostring(iib):sub(1,80)or nil}
F.saveSoon()
if hib then
local jib=(N.prof()or{}).level_data or{}
local kib={}
for lib,mib in ipairs(U.list(Xhb.levels))do
if mib.id~=Qhb.id and not bib[mib.id]and W.done(jib,mib.id,QWd[2222])then
table.insert(kib,W.levelName(mib.id))
end
end
F.log(1,QWd[2393],string.format(QWd[3132],Yhb,#kib>0 and(QWd[3133]..table.concat(kib,QWd[1916]))or QWd[3134],iib and(QWd[3135]..tostring(iib))or QWd[729]))
W.lastScored=nil
else
F.log(1,QWd[2393],string.format(QWd[3136],Yhb,tostring(iib or(fib and gib)or QWd[2364])))
end
end
