end
return ynb>=5 and(tonumber(xnb.streak)or 0)==0 and znb/ynb>=0.9
end
function ab.unitLab(Cnb)
if not ab.unitLabSafe(Cnb)then
return
end
P.unitLab=type(P.unitLab)==QWd[1805]and P.unitLab or{}
local Dnb=P.unitLab
Dnb.tried=type(Dnb.tried)==QWd[1805]and Dnb.tried or{}
Dnb.seen=(tonumber(Dnb.seen)or 0)+1
if Dnb.seen%ab.LAB.EVERY~=0 then
return
end
local Enb=N.session()
local Fnb=V.equipped()
if not Enb or#Fnb<2 then
return
end
local Gnb={}
for Hnb,Inb in ipairs(Fnb)do
Gnb[Inb.uuid]=true
Gnb[Inb.id]=true
end
local Jnb,Knb,Lnb
for Mnb,Nnb in pairs(Enb.profile_data.collection.owned_units)do
local Onb=Nnb.unit_id
if not Gnb[Mnb]and not Gnb[Onb]and N.Units[Onb]and not V.isFarm(Onb)and not V.allyBuff(Onb)and os.time()-(tonumber(Dnb.tried[Onb])or 0)>ab.LAB.AGAIN then
local Pnb=ab.unitEvidence(Onb)
if Pnb<ab.LAB.MIN_EVIDENCE then
local Qnb=Enb.collection:get_unit_by_uuid(Mnb)or Nnb
local Rnb=jb.score(Qnb)
if Rnb>0 and(not Jnb or Pnb<Knb or(Pnb==Knb and Rnb>Lnb))then
Jnb,Knb,Lnb={uuid=Mnb,id=Onb,u=Qnb},Pnb,Rnb
end
end
end
end
if not Jnb then
return
end
local Snb,Tnb
for Unb,Vnb in ipairs(Fnb)do
if not V.isFarm(Vnb.id)and not V.allyBuff(Vnb.id)and Vnb.uuid~=O.evolveUnit then
local Wnb=jb.score(Vnb.u)
if not Snb or Wnb<Tnb then
Snb,Tnb=Vnb,Wnb
end
end
end
if not Snb then
return
end
Dnb.tried[Jnb.id]=os.time()
local Xnb=0
for Ynb in pairs(Dnb.tried)do
Xnb=Xnb+1
if Xnb>300 then
Dnb.tried[Ynb]=nil
end
end
local Znb,_nb=fb.levelFor(Cnb)
if not Znb then
return
end
local aob=fb.info(Znb,Cnb.key,_nb,Cnb.mod or W.ldMod(Znb)or W.levelMod(Cnb.level))
local bob={}
for cob,dob in ipairs(Fnb)do
table.insert(bob,dob.uuid==Snb.uuid and Jnb.u or dob.u)
end
local eob,fob=pcall(fb.run,aob,fb.teamFrom(bob,aob.map),{hpMul=1.1})
local gob=eob and type(fob)==QWd[1805]and(fob.won or(aob.infinite and(tonumber(fob.wave)or 0)>=0.8*W.infReach(Cnb.key)))
if not gob then
F.log(2,QWd[3265],string.format(QWd[3266],V.name(Jnb.id),Cnb.label))
return
end
local hob={}
for iob,kob in ipairs(Fnb)do
table.insert(hob,kob.uuid==Snb.uuid and Jnb.uuid or kob.uuid)
end
if ab.equipTeam(hob,QWd[3267]..V.name(Jnb.id))then
Dnb.now={id=Jnb.id,out=Snb.id,key=Cnb.key,at=os.time(),ev=Knb}
F.log(1,QWd[3265],string.format(QWd[3268],V.name(Jnb.id),V.name(Snb.id),Cnb.label,Knb))
F.saveNow()
end
end
function ab.unitLabDone(lob)
