function eb.upgradeGain(Trb,Urb,Vrb,Wrb,Xrb,Yrb)
local Zrb,_rb=Urb[Vrb],Urb[Vrb+1]
local asb=(Zrb.cd>0 and Zrb.damage/Zrb.cd or 0)
local bsb=(_rb.cd>0 and _rb.damage/_rb.cd or 0)*V.aoe(_rb.atk,_rb.range)/math.max(0.3,V.aoe(Zrb.atk,Zrb.range))
local csb=asb>0 and Trb*(bsb/asb-1)or(Yrb or 0)
local dsb=Urb[Vrb+2]
if dsb and Vrb+1<Urb.max and dsb.cd>0 and _rb.cd>0 and asb>0 then
local esb=Trb*((dsb.damage/dsb.cd)/asb-1)
local fsb=Wrb+dsb.cost*Xrb
if esb/fsb>csb/Wrb then
csb=csb+(esb/fsb*Wrb-csb)*0.5
end
end
local gsb=(_rb.range or 0)>(Zrb.range or 0)and(1+((_rb.range-Zrb.range)/math.max(1,Zrb.range)))or 1
return math.max(0,csb)*gsb
end
function eb.dpsFor(hsb,isb)
if isb<=0 then
return 0
end
local jsb={}
for ksb,lsb in ipairs(hsb)do
if not lsb.farm and lsb.gain>0 then
table.insert(jsb,lsb)
end
end
table.sort(jsb,function(msb,nsb)
return msb.gain/msb.cost>nsb.gain/nsb.cost
end)
local osb,psb=0,0
for qsb,rsb in ipairs(jsb)do
if isb<=0 then
break
end
psb=rsb.gain/rsb.cost
local ssb=math.min(1,isb/rsb.cost)
osb=osb+rsb.gain*ssb
isb=isb-rsb.cost*ssb
end
return osb+math.max(0,isb)*psb*0.7
end
function eb.shieldDps(tsb,usb,vsb,wsb,xsb,ysb,zsb)
if(wsb or 0)<=0 or(tsb or 0)<=0 or(xsb or 0)<=0 then
return tsb or 0
end
usb,vsb,ysb=math.max(0.3,usb or 2),math.max(1,vsb or 1),ysb or 1
local Asb=tsb*ysb*usb/vsb
return xsb*vsb/((wsb/math.max(1,zsb or 1)+math.max(1,xsb/Asb))*usb)/ysb
end
function eb.shieldGain(Bsb,Csb,Dsb,Esb,Fsb,Gsb,Hsb,Isb)
local Jsb,Ksb=V.attackInfo(Csb.atk,Csb.range),V.attackInfo(Esb.atk,Esb.range)
local Lsb=eb.shieldDps(Bsb,(tonumber(Csb.cd)or 2)*(Hsb or 1),Jsb.n,Fsb,Gsb,Isb,Jsb.hits)
local Msb=eb.shieldDps(Dsb,(tonumber(Esb.cd)or 2)*(Hsb or 1),Ksb.n,Fsb,Gsb,Isb,Ksb.hits)
local Nsb=math.max(0,((tonumber(Esb.range)or 0)-(tonumber(Csb.range)or 0))/math.max(1,tonumber(Csb.range)or 1))
return math.max(0,Msb-Lsb)+Lsb*Nsb
end
function eb.shieldWork(Osb,Psb,Qsb,Rsb,Ssb,Tsb,Usb,Vsb,Wsb)
if(Rsb or 0)<=0 then
return 0
end
local Xsb=3*Rsb*(Ssb or 1)/math.max(1,Tsb or 20)
if(Qsb or 0)>=Xsb then
return 0
end
return math.max(1,Osb or 1)*math.max(1,Wsb or 1)/math.max(0.3,Psb or 2)*math.min(Usb or 0,Vsb or 0)
end
function eb.holdGain(Ysb,Zsb,_sb,atb)
if not Ysb or(Zsb or 0)<=0 then
return 0
end
local btb,ctb=tonumber(Ysb.stun)or 0,tonumber(Ysb.slowTime)or 0
if btb<=0 and ctb<=0 then
return 0
end
local dtb,etb=btb>0 and btb or ctb,btb>0 and 1 or(tonumber(Ysb.slowPct)or 0.3)
local ftb=etb*dtb/(dtb+(tonumber(Ysb.ccCd)or 8))
local gtb=ftb/math.max(0.1,1-ftb)
return Zsb*gtb*U.clamp(_sb or 0.5,0,1)*math.min(1,(tonumber(Ysb.n)or 1)/2)/(1+(atb or 0))
end
function eb.bleedGain(htb,itb,jtb,ktb)
if(htb or 0)<=0 then
return 0
end
local ltb=itb or 0
for mtb,ntb in ipairs(jtb or{})do
ltb=math.max(ltb,(tonumber(ntb.hp)or 0)*0.5)
end
return htb*ltb*(ktb and 0.5 or 1)
end
function eb.bleedShare(otb,ptb,qtb,rtb)
if otb<=0 or not ptb then
return 0
end
if rtb then
return ptb==0 and otb or otb/(ptb+1)
end
return qtb<ptb and otb/(ptb-qtb)or 0
end
function eb.keepsUp(stb,ttb,utb,vtb,wtb)
local xtb=stb.coming
if not(xtb and#xtb>0 and stb.waveSec)then
return true
end
local ytb=stb.eff or 1
local ztb=stb.money-utb
local Atb=(stb.teamDps or 0)*(stb.shieldK or 1)+(vtb or 0)*ytb+eb.dpsFor(ttb,math.max(0,ztb))*ytb
local Btb=(stb.farmNow or 0)+(wtb or 0)
local Ctb=(stb.roadSec or 130)*U.clamp(stb.cover or 0.6,0.1,1)
local Dtb=stb.hpAlive or 0
for Etb,Ftb in ipairs(xtb)do
Dtb=math.max(0,Dtb+Ftb.hp-Atb*stb.waveSec)
local Gtb=Atb*Ctb
if Dtb>Gtb then
return false,Etb,Gtb/math.max(1,Dtb)
end
if Etb< #xtb then
Atb=Atb+eb.dpsFor(ttb,(Ftb.reward or 0)+Btb)*ytb*(0.85^Etb)
end
end
return true
end
function eb.decide(Htb,Itb)
local Jtb=U.clamp(Itb.cover or 0.6,0.1,1)
local Ktb=math.max(O.clearSec,0.7*(Itb.roadSec or 50)*Jtb)
local Ltb=(Itb.clearSec or 0)>Ktb
Itb.piling=Itb.piling and Ltb
local Mtb=Itb.attackers>0 and Itb.pressure<math.min(O.safeReach,Jtb*0.75)and not Itb.piling and not Ltb
local Ntb=Itb.pressure>=math.min(O.dangerReach,Jtb*0.9)or(Itb.piling and Itb.enemies>=18)
local Otb,Ptb
for Qtb,Rtb in ipairs(Htb)do
if Rtb.farm then
if O.farmUnits and Rtb.gain>0 then
Rtb.payback=Rtb.cost/Rtb.gain
if Itb.left-1>=Rtb.payback+(Itb.farmSpare or O.farmSpare)and(not Otb or Rtb.payback<Otb.payback)then
Otb=Rtb
end
end
else
Rtb.ratio=Rtb.gain/math.max(1,Rtb.cost)
if not Ptb or Rtb.ratio>Ptb.ratio then
Ptb=Rtb
end
end
end
if Itb.leak and Itb.attackers>0 then
local Stb
for Ttb,Utb in ipairs(Htb)do
local Vtb=not Itb.airLeak or(Utb.e and bb.cardAir(Utb.e.id))
if Utb.place and not Utb.farm and Vtb and Utb.cost<=Itb.money and not(Utb.e and V.allyBuff(Utb.e.id))and(not Stb or Utb.gain>Stb.gain)then
Stb=Utb
end
end
if Stb then
return Stb,string.format(QWd[3369],math.floor(Itb.leak*100))
end
end
local Wtb=Itb.future<Itb.wantLeft*1.1
local Xtb,Ytb,Ztb=true,nil,nil
if Otb then
Xtb,Ytb,Ztb=eb.keepsUp(Itb,Htb,Otb.cost,0,Otb.gain)
end
local _tb=Itb.coming and not eb.keepsUp(Itb,Htb,0,0,0)
local aub=false
if bb.random and Otb and not Ntb and Itb.attackers>=2 and Otb.payback<=Itb.left/3 then
local bub=0
for cub,dub in ipairs(bb.mine or{})do
if V.isFarm(dub._stats.id.Value)then
bub=bub+1
end
end
aub=not Otb.place or bub<4
end
if _tb and Itb.attackers>0 then
Ntb=true
end
local eub=math.max(1,Itb.incomeRate or 20)
local fub=Itb.waveSec or 20
local function gub(hub,iub,jub)
local kub=math.max(0,(hub.cost-Itb.money)/eub)
local lub=hub.gain*math.max(0,jub-kub)
if iub then
local mub=math.max(0,Itb.money-hub.cost)
local nub=kub+math.max(0,(iub.cost-mub)/eub)
lub=lub+iub.gain*math.max(0,jub-nub)
end
return lub
end
local oub,pub
if Itb.attackers==0 and Ptb then
local qub=4*fub
local rub={}
for tub,uub in ipairs(Htb)do
if uub.place and not uub.farm then
table.insert(rub,{o=uub,v=gub(uub,nil,qub)})
end
end
table.sort(rub,function(vub,wub)
return vub.v>wub.v
end)
local xub=Itb.opener and rub[Itb.opener]and Itb.opener or 1
local yub=rub[xub]and rub[xub].o
oub,pub=yub or Ptb,xub>1 and QWd[3370]or QWd[3371]
elseif Otb and Mtb and Wtb and not Ntb and Xtb then
oub=Otb
pub=string.format(QWd[3372],Otb.payback,Itb.left,Itb.coming and#Itb.coming or 0)
elseif aub then
oub=Otb
pub=string.format(QWd[3373],Otb.payback,Itb.left)
elseif Ptb then
oub=Ptb
if _tb then
pub=string.format(QWd[3374])
elseif Ntb then
pub=string.format(QWd[3375],math.floor(Itb.pressure*100),math.floor(Jtb*100))
elseif Otb and not Xtb then
pub=string.format(QWd[3376],Ytb or 1,math.floor((Ztb or 0)*100))
elseif Otb and Ltb then
pub=string.format(QWd[3377],math.min(999,math.floor(Itb.clearSec)),math.floor(Ktb))
elseif Otb and Itb.piling then
pub=string.format(QWd[3378],Itb.enemies)
elseif Otb and not Mtb then
pub=QWd[3379]
elseif Otb and not Wtb then
pub=QWd[3380]
else
pub=QWd[3381]
end
end
if not oub then
return nil
end
if oub.cost>Itb.money then
local zub
if not oub.farm then
local Aub=((Itb.pressure or 0)>=0.95 and 0.5 or Ntb and 2 or 6)*fub
local Bub
for Cub,Dub in ipairs(Htb)do
if not Dub.farm and Dub~=oub and Dub.cost<=Itb.money then
local Eub=gub(Dub,oub,Aub)
local Fub=gub(oub,Dub,Aub)
if Eub>Fub and(not Bub or Eub>Bub)then
zub,Bub=Dub,Eub
end
end
end
end
if not zub then
return nil,nil,string.format(QWd[3382],U.fmt(oub.cost),oub.what or QWd[2032],math.ceil((oub.cost-Itb.money)/eub),math.floor(eub),pub),{cost=oub.cost,what=oub.what,sec=math.ceil((oub.cost-Itb.money)/eub),rate=math.floor(eub),why=pub}
end
oub,pub=zub,pub..QWd[3383]
end
return oub,pub
end
