return(fb.objective(VTb)+fb.objective(fb.run(gTb,WTb,{hpMul=mTb*0.92}))+fb.objective(fb.run(gTb,WTb,{hpMul=mTb*1.08})))/3
end
local XTb,YTb=zTb or nTb,TTb(lTb,zTb or nTb)
if type(iTb.rest)==QWd[1805]and#iTb.rest>0 then
local ZTb,_Tb
for aUb,bUb in ipairs(lTb)do
if not V.isFarm(bUb.unit_id)and not V.allyBuff(bUb.unit_id)then
local cUb,dUb=pcall(V.score,bUb,gTb.mod)
dUb=(cUb and dUb or 0)*V.skinMul(bUb,gTb.skinSet)
if not _Tb or dUb<_Tb then
ZTb,_Tb=aUb,dUb
end
end
end
if ZTb then
local eUb,fUb={},U.now()
for gUb,hUb in ipairs(iTb.rest)do
if U.now()-fUb>5 then
break
end
local iUb=false
for jUb,kUb in ipairs(lTb)do
if kUb.unit_id==hUb.unit_id then
iUb=true
end
end
if not iUb then
local lUb=table.clone(lTb)
lUb[ZTb]=hUb
table.insert(eUb,{u=hUb,o=fb.objective(fb.run(gTb,fb.teamFrom(lUb,gTb.map),{hpMul=mTb}))})
end
end
table.sort(eUb,function(mUb,nUb)
return mUb.o>nUb.o
end)
iTb=table.clone(iTb)
for oUb=1,math.min(4,#eUb)do
table.insert(iTb,1,eUb[oUb].u)
end
kTb=kTb+(U.now()-fUb)
end
end
for pUb=1,2 do
local qUb=false
for rUb=1,#lTb do
for sUb,tUb in ipairs(iTb)do
if U.now()-kTb>jTb then
return lTb,XTb,mTb,nTb
end
local uUb=false
for vUb,wUb in ipairs(lTb)do
if wUb.unit_id==tUb.unit_id then
uUb=true
end
end
if not uUb then
local xUb=table.clone(lTb)
xUb[rUb]=tUb
if(not tTb or oTb(xUb)>0)and uTb(xUb)>=math.min(8,uTb(lTb))then
local yUb=fb.run(gTb,fb.teamFrom(xUb,gTb.map),{hpMul=mTb})
local zUb=fb.objective(yUb)
if zUb>YTb+1 then
zUb=TTb(xUb,yUb)
if zUb>YTb+1 then
lTb,YTb,XTb,qUb=xUb,zUb,yUb,true
end
end
end
end
end
end
if not qUb then
break
end
end
