table.insert(Qbc,{p=U.flat(Sbc:GetPivot().Position),r=Tbc.range.Value*(V.SUMMONER[Tbc.id.Value]and V.SUMMONER[Tbc.id.Value].reach or 1),air=bb.canAir(Sbc)})
