local Ubc,Vbc=0,0
if#Qbc>0 then
for Wbc,Xbc in ipairs(bb.samples)do
if Xbc.prog>Vbc then
local Ybc=U.flat(Xbc.pos)
for Zbc,_bc in ipairs(Qbc)do
if(Ybc-_bc.p).Magnitude<=_bc.r then
if Xbc.prog>Ubc then
Ubc=Xbc.prog
end
if _bc.air then
Vbc=Xbc.prog
break
end
end
end
end
end
