local ccc={}
for dcc,ecc in ipairs(bb.samples)do
local fcc=U.flat(ecc.pos)
for gcc,hcc in ipairs(Qbc)do
if(fcc-hcc.p).Magnitude<=hcc.r then
local icc=tostring(ecc.lane)
ccc[icc]=(ccc[icc]or 0)+1
if ecc.prog>(acc[icc]or 0)then
acc[icc]=ecc.prog
end
break
end
end
end
local jcc,kcc={},0
for lcc,mcc in pairs(bcc.by)do
jcc[lcc]=(ccc[lcc]or 0)/math.max(1,mcc)
kcc=math.max(kcc,jcc[lcc])
end
bb.laneW={}
for ncc,occ in pairs(bcc.by)do
bb.laneW[ncc]=(bcc.avg/math.max(1,occ))*(1+1.5*(kcc>0 and(1-jcc[ncc]/kcc)or 0))
end
bb.laneFrac=jcc
else
bb.laneW,bb.laneFrac=nil,nil
end
local pcc,qcc,rcc
if#Qbc>0 then
for scc,tcc in ipairs(Pbc)do
local ucc=(bb.laneW and tcc.lane)and(acc[tostring(tcc.lane)]or 0)or Ubc
if tcc.hp>0 and tcc.prog>ucc+0.02 and tcc.prog>(pcc or 0)then
pcc,rcc=tcc.prog,bb.laneW and tcc.lane or nil
end
if tcc.hp>0 and tcc.fly and tcc.prog>Vbc+0.02 then
qcc=true
end
end
end
local vcc= #Qbc>0 and(bb.pressure or 0)>=Ubc-0.08
return{covEnd=Ubc,airEnd=Vbc,leak=pcc,leakLane=rcc,covL=acc,airLeak=qcc,push=vcc,units= #Qbc}
end
