function bb.nearSpot(soc,toc,uoc)
local voc,woc=nil,9
for xoc,yoc in ipairs(soc or{})do
local zoc=(yoc.X-toc)^2+(yoc.Z-uoc)^2
if zoc<=woc then
voc,woc=yoc,zoc
end
end
return voc
end
function bb.baseRange(Aoc)
local Boc=V.rows(Aoc)
local Coc=Boc and Boc[Boc.max]and tonumber(Boc[Boc.max].range)
return Coc or(N.Units[Aoc]and tonumber(N.Units[Aoc].range))or nil
end
function bb.studyMoves(Doc,Eoc)
local Foc=V.rows(Doc.id)
local Goc=V.range(Doc.e.u,Foc.max)*Eoc
local Hoc=Goc*Goc
local Ioc,Joc={},{}
for Koc,Loc in ipairs(Doc.spots or{})do
local Moc,Noc,Ooc,Poc,Qoc=0,0,0,0,0
for Roc,Soc in ipairs(bb.samples)do
local Toc,Uoc=Soc.pos.X-Loc.X,Soc.pos.Z-Loc.Z
if Toc*Toc+Uoc*Uoc<=Hoc then
Ooc=Ooc+1
local Voc=math.min(49,math.floor(Soc.prog*50))
if Voc<25 then
Moc=bit32 .bor(Moc,bit32 .lshift(1,Voc))
else
Noc=bit32 .bor(Noc,bit32 .lshift(1,Voc-25))
end
if Soc.prog<=0.3 then
Poc=Poc+1
elseif Soc.prog>=0.7 then
Qoc=Qoc+1
end
end
end
if Ooc>0 then
local Woc=Moc..QWd[1931]..Noc
local Xoc=Ioc[Woc]
if not Xoc then
Xoc={p=Loc,lo=Moc,hi=Noc,n=Ooc,early=Poc,late=Qoc}
Ioc[Woc]=Xoc
table.insert(Joc,Xoc)
elseif Ooc>Xoc.n then
Xoc.p,Xoc.n,Xoc.early,Xoc.late=Loc,Ooc,Poc,Qoc
end
end
if Koc%40==0 then
task.wait()
end
end
local Yoc={}
for Zoc,_oc in ipairs(Joc)do
local apc=false
for bpc,cpc in ipairs(Joc)do
if Zoc~=bpc and cpc.n>=_oc.n and bit32 .band(_oc.lo,cpc.lo)==_oc.lo and bit32 .band(_oc.hi,cpc.hi)==_oc.hi and(cpc.lo~=_oc.lo or cpc.hi~=_oc.hi or cpc.n>_oc.n)then
apc=true
break
end
end
if not apc then
table.insert(Yoc,_oc)
end
if Zoc%40==0 then
task.wait()
end
end
local dpc,epc={},{}
local function fpc(gpc)
if gpc and not epc[gpc]then
epc[gpc]=true
table.insert(dpc,gpc)
end
end
table.sort(Yoc,function(hpc,ipc)
return hpc.n>ipc.n
end)
for jpc=1,math.min(bb.STUDY_K,#Yoc)do
fpc(Yoc[jpc].p)
end
table.sort(Yoc,function(kpc,lpc)
return kpc.early>lpc.early
end)
fpc(Yoc[1]and Yoc[1].p)
fpc(Yoc[2]and Yoc[2].p)
table.sort(Yoc,function(mpc,npc)
return mpc.late>npc.late
end)
fpc(Yoc[1]and Yoc[1].p)
fpc(Yoc[2]and Yoc[2].p)
local opc=0
for ppc,qpc in ipairs(bb.hiveSpots(bb.ld and bb.ld.map))do
if opc>=bb.STUDY_SHARED then
break
end
local rpc=false
for spc,tpc in ipairs(type(qpc.units)==QWd[1805]and qpc.units or{})do
local upc=tpc==Doc.id and Goc or((bb.baseRange(tpc)or 0)*Eoc)
if tpc==Doc.id or(upc>0 and math.abs(upc-Goc)<=0.3*Goc)then
rpc=true
break
end
end
local vpc=rpc and tonumber(qpc.x)and tonumber(qpc.z)and bb.nearSpot(Doc.spots,tonumber(qpc.x),tonumber(qpc.z))or nil
if vpc and not epc[vpc]then
fpc(vpc)
opc=opc+1
end
end
return dpc,#Joc,#Yoc,opc
end
function bb.studyRun(wpc)
local xpc=U.now()
while F.alive and not(bb.finished or bb.result)and(bb.planning or U.now()-xpc<20)do
task.wait(1)
end
local function ypc()
return F.alive and not(bb.finished or bb.result)and O.mapStudy~=false and F.where==QWd[1876]
end
if not ypc()then
return
end
local zpc,Apc,Bpc=wpc.info,wpc.team,wpc.base
local Cpc=zpc.timeLimit~=nil
local Dpc=Cpc and 1 or math.max(1,tonumber(wpc.hard)or 1)
local Epc={Dpc*0.95,Dpc*1.05}
local Fpc=bb.bookFor(zpc)
local Gpc={key=wpc.key,label=bb.label(),n=Fpc and tonumber(Fpc.n)or 0,run=0,timed=Cpc,kills=zpc.killScore and true or nil,hp=Dpc,at=os.time()}
bb.study=Gpc
local Hpc,Ipc,Jpc,Kpc,Lpc={},0,0,0,0
for Mpc,Npc in ipairs(wpc.attackers)do
