Hpc[Npc.id]=Opc
Ipc,Jpc,Kpc,Lpc=Ipc+ #(Npc.spots or{}),Jpc+Ppc,Kpc+ #Opc,Lpc+Rpc
if not ypc()then
return
end
end
Gpc.moves=Kpc
F.log(1,QWd[2522],string.format(QWd[3925],Gpc.label,Ipc,Jpc,Kpc,Lpc>0 and string.format(QWd[3926],Lpc)or QWd[729]))
local Spc={}
local function Tpc(Upc)
return{samples=bb.samples,cache=Spc,spots=Upc,style=Bpc.style,list=Bpc.list,hybridHill=Bpc.hybridHill}
end
local function Vpc(Wpc)
local Xpc=0
for Ypc,Zpc in pairs(Wpc)do
local _pc=bb.spotRec(Ypc,Zpc)
if _pc then
Xpc=Xpc+(tonumber(_pc.wins)or 0)*200-((tonumber(_pc.runs)or 0)-(tonumber(_pc.wins)or 0))*1500
end
end
return Xpc
end
local function aqc(bqc)
local cqc,dqc,eqc=0,0,0
for fqc,gqc in ipairs(Epc)do
local hqc=os.clock()
local iqc=fb.runRaw(zpc,Apc,{hpMul=gqc,layout=Tpc(bqc),bg=true})
cqc,dqc,eqc=cqc+fb.objective(iqc),dqc+(tonumber(iqc.kills)or 0),eqc+(tonumber(iqc.wave)or 0)
task.wait(math.clamp((os.clock()-hqc)*3,0.25,wpc.pauseMax or 1.5))
if not ypc()then
return nil
end
end
Gpc.n,Gpc.run=Gpc.n+1,Gpc.run+1
return cqc/ #Epc*100+Vpc(bqc),dqc/ #Epc,eqc/ #Epc
end
local function jqc(kqc)
local lqc={}
for mqc,nqc in pairs(kqc)do
lqc[mqc]=nqc
end
return lqc
end
local function oqc(pqc,qqc,rqc)
for sqc,tqc in pairs(pqc)do
if sqc~=qqc and(U.flat(tqc)-U.flat(rqc)).Magnitude<4.5 then
return true
end
end
return false
end
local uqc={spots=jqc(Bpc.spots)}
uqc.s,uqc.kills,uqc.wave=aqc(uqc.spots)
