end
Gpc.baseKills,Gpc.baseWave=uqc.kills,uqc.wave
Gpc.bestKills,Gpc.bestWave=uqc.kills,uqc.wave
if Fpc and Fpc.aside==nil then
local vqc,wqc=jqc(uqc.spots),0
for xqc,yqc in ipairs(wpc.attackers)do
local zqc=Fpc.spots[yqc.id]
local Aqc=type(zqc)==QWd[1805]and tonumber(zqc[1])and tonumber(zqc[3])and bb.nearSpot(yqc.spots,tonumber(zqc[1]),tonumber(zqc[3]))or nil
if Aqc and Aqc~=vqc[yqc.id]and not oqc(vqc,yqc.id,Aqc)then
vqc[yqc.id]=Aqc
wqc=wqc+1
end
end
if wqc>0 then
local Bqc,Cqc,Dqc=aqc(vqc)
if not Bqc then
return bb.studyEnd(Gpc,wpc,uqc)
end
if Bqc>uqc.s then
uqc={spots=vqc,s=Bqc,kills=Cqc,wave=Dqc}
Gpc.bestKills,Gpc.bestWave=Cqc,Dqc
end
end
end
local Eqc,Fqc=U.now(),Gpc.run
local function Gqc(Hqc)
if not(Hqc.s and Hqc.s>uqc.s+math.max(50,math.abs(uqc.s)*0.005))then
return false
end
uqc=Hqc
Gpc.bestKills,Gpc.bestWave,Gpc.better=Hqc.kills,Hqc.wave,(Gpc.better or 0)+1
pcall(bb.bookSave,zpc,wpc,uqc,Gpc)
return true
end
local function Iqc()
if Gpc.run-Fqc>=60 or U.now()-Eqc>240 then
Eqc,Fqc=U.now(),Gpc.run
F.log(1,QWd[2522],bb.studyWords(Gpc))
end
end
local Jqc={uqc}
for Kqc,Lqc in ipairs(wpc.attackers)do
local Mqc={}
for Nqc,Oqc in ipairs(Jqc)do
table.insert(Mqc,Oqc)
for Pqc,Qqc in ipairs(Hpc[Lqc.id]or{})do
if Qqc~=Oqc.spots[Lqc.id]and not oqc(Oqc.spots,Lqc.id,Qqc)then
local Rqc=jqc(Oqc.spots)
Rqc[Lqc.id]=Qqc
local Sqc,Tqc,Uqc=aqc(Rqc)
