return bb.studyEnd(Gpc,wpc,uqc)
end
local Vqc={spots=Rqc,s=Sqc,kills=Tqc,wave=Uqc}
table.insert(Mqc,Vqc)
Gqc(Vqc)
Iqc()
end
end
end
table.sort(Mqc,function(Wqc,Xqc)
