end)
Jqc={}
for Yqc=1,math.min(bb.STUDY_BEAM,#Mqc)do
table.insert(Jqc,Mqc[Yqc])
end
end
local Zqc={}
for _qc,arc in ipairs(wpc.attackers)do
if Hpc[arc.id]and#Hpc[arc.id]>0 then
table.insert(Zqc,arc.id)
end
end
while ypc()and#Zqc>0 do
local brc=jqc(uqc.spots)
for crc=1,math.min(2,#Zqc)do
local drc=Zqc[math.random(#Zqc)]
