local frc=erc[math.random(#erc)]
if not oqc(brc,drc,frc)then
brc[drc]=frc
end
end
local grc,hrc,irc=aqc(brc)
if not grc then
break
end
Gqc({spots=brc,s=grc,kills=hrc,wave=irc})
Iqc()
end
bb.studyEnd(Gpc,wpc,uqc)
end
