function bb.validOpen(jrc,krc)
local lrc=N.PC.raycast(jrc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not lrc then
return nil
end
if not N.PC.is_valid_raycast_hit(lrc.Instance,krc)then
return nil
end
local mrc=lrc.Position
if bb.blockedSpot(mrc)then
return nil
end
local nrc=(tonumber(krc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(nrc*2,2.5,nrc*2)
bb.probe.CFrame=CFrame.new(mrc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return mrc
end
function bb.studyInfinite()
if O.mapStudy==false or not(bb.info and bb.infinite)or bb.kind==QWd[2233]then
return
end
local orc=bb.info
local function prc()
