if not V.isFarm(urc.id)and not V.allyBuff(urc.id)and urc.uuid~=bb.trainee and V.rows(urc.id)then
local vrc,wrc=pcall(V.score,urc.u,bb.mod)
table.insert(rrc,{e=urc,id=urc.id,sc=vrc and wrc or 0})
end
end
if#rrc==0 then
return
end
table.sort(rrc,function(xrc,yrc)
return xrc.sc>yrc.sc
end)
local function zrc()
local Arc,Brc={},0
for Crc,Drc in ipairs(rrc)do
for Erc,Frc in ipairs(bb.mine or{})do
