local Prc=Orc and bb.hybridHill
local Qrc=((Nrc.hill_unit or Prc)and QWd[2548]or(Orc and QWd[3866])or QWd[3867])..QWd[1931]..tostring(Nrc.override_hitbox_radius or QWd[729])
