local Wrc={info=orc,team=fb.teamFrom(qrc,orc.map),key=bb.bookKey(orc),hard=1,scale=tonumber(orc.rangeScale)or 1,attackers={},pauseMax=4,inf=true}
local Xrc={spots={},style=QWd[2697],hybridHill=bb.hybridHill and true or false}
