function bb.bookSave(hsc,isc,jsc,ksc)
P.mapBook=type(P.mapBook)==QWd[1805]and P.mapBook or{}
local lsc={}
for msc,nsc in pairs(jsc.spots or{})do
lsc[msc]={math.floor(nsc.X*10+0.5)/10,math.floor(nsc.Y*10+0.5)/10,math.floor(nsc.Z*10+0.5)/10}
