bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3*24*3600,0.015,300
function bb.layoutRecFor(Qsc,Rsc)
local Ssc=bb.bookKey(Qsc)
P.layoutRec=type(P.layoutRec)==QWd[1805]and P.layoutRec or{}
local Tsc=P.layoutRec[Ssc]
if type(Tsc)~=QWd[1805]then
if not Rsc then
return nil
end
Tsc={at=os.time()}
P.layoutRec[Ssc]=Tsc
if U.count(P.layoutRec)>80 then
local Usc,Vsc
for Wsc,Xsc in pairs(P.layoutRec)do
local Ysc=type(Xsc)==QWd[1805]and tonumber(Xsc.at)or 0
if not Vsc or Ysc<Vsc then
Usc,Vsc=Wsc,Ysc
end
end
P.layoutRec[Usc]=nil
end
end
return Tsc
end
function bb.layoutAdd(Zsc,_sc,atc,btc,ctc)
Zsc.runs,Zsc.wins=(tonumber(Zsc.runs)or 0)+1,(tonumber(Zsc.wins)or 0)+(_sc and 1 or 0)
Zsc.sec,Zsc.wave=type(Zsc.sec)==QWd[1805]and Zsc.sec or{},type(Zsc.wave)==QWd[1805]and Zsc.wave or{}
if _sc and tonumber(atc)then
table.insert(Zsc.sec,math.floor(atc+0.5))
end
table.insert(Zsc.wave,tonumber(btc)or 0)
if tonumber(ctc)then
Zsc.kills=type(Zsc.kills)==QWd[1805]and Zsc.kills or{}
table.insert(Zsc.kills,math.floor(tonumber(ctc)))
while#Zsc.kills>bb.LAYOUT_KEEP do
table.remove(Zsc.kills,1)
end
end
while#Zsc.sec>bb.LAYOUT_KEEP do
table.remove(Zsc.sec,1)
end
while#Zsc.wave>bb.LAYOUT_KEEP do
table.remove(Zsc.wave,1)
end
end
function bb.layoutJudge(dtc,etc,ftc,gtc)
local htc,itc=tonumber(dtc and dtc.runs)or 0,tonumber(etc and etc.runs)or 0
if htc<1 or itc<bb.LAYOUT_CONTROL then
return nil
end
if gtc and type(dtc.kills)==QWd[1805]and type(etc.kills)==QWd[1805]and#dtc.kills>=1 and#etc.kills>=bb.LAYOUT_CONTROL then
local jtc,ktc=bb.labMedian(dtc.kills),bb.labMedian(etc.kills)
if jtc and ktc and jtc<ktc*0.97 and(#dtc.kills>=2 or jtc<ktc*0.85)then
return string.format(QWd[3937],jtc,ktc)
end
return nil
end
local ltc,mtc=(tonumber(dtc.wins)or 0)/htc,(tonumber(etc.wins)or 0)/itc
if not ftc and mtc>=0.5 then
if ltc+0.25<mtc and(htc>=2 or(ltc==0 and mtc>=0.9 and itc>=3))then
return string.format(QWd[3938],tonumber(dtc.wins)or 0,htc,htc==1 and QWd[729]or QWd[1653],tonumber(etc.wins)or 0,itc)
end
local ntc,otc=bb.labMedian(dtc.sec),bb.labMedian(etc.sec)
if ntc and otc and ntc>otc*1.10 and(#dtc.sec>=2 or ntc>otc*1.25)then
return string.format(QWd[3939],math.floor(ntc/60),ntc%60,math.floor(otc/60),otc%60)
end
return nil
end
local ptc,qtc=bb.labMedian(dtc.wave),bb.labMedian(etc.wave)
if ptc and qtc and ptc<qtc-math.max(1,qtc*0.03)and(htc>=2 or ptc<qtc*0.85)then
return string.format(QWd[3940],ptc,qtc)
end
return nil
end
function bb.layoutResult(rtc,stc)
local ttc=bb.info
local utc=bb.layoutSrc
if not(ttc and utc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not ttc.timeLimit then
return
end
local vtc=bb.wave()
local wtc=bb.layoutRecFor(ttc,true)
wtc.at=os.time()
local xtc=ttc.timeLimit~=nil
local ytc=ttc.killScore and true or nil
local ztc=ytc and(bb.killsEnd or bb.realKills())or nil
if utc==QWd[3909]then
local Atc=bb.bookFor(ttc)
if not Atc then
return
end
Atc.real=type(Atc.real)==QWd[1805]and Atc.real or{}
bb.layoutAdd(Atc.real,rtc,stc,vtc,ztc)
local Btc=Atc.aside==nil and bb.layoutJudge(Atc.real,wtc.own,xtc,ytc)or nil
if Btc then
Atc.aside={at=os.time(),why=Btc}
F.log(1,QWd[3859],string.format(QWd[3941],Btc))
end
else
wtc[utc]=type(wtc[utc])==QWd[1805]and wtc[utc]or{}
local Ctc=wtc[utc]
bb.layoutAdd(Ctc,rtc,stc,vtc,ztc)
if utc==QWd[3326]and Ctc.aside==nil then
local Dtc=bb.layoutJudge(Ctc,wtc.own,xtc,ytc)
if Dtc then
Ctc.aside,Ctc.why=os.time(),Dtc
F.log(1,QWd[3859],string.format(QWd[3942],Dtc,math.floor(bb.HIVE_ASIDE/86400)))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={QWd[3943],QWd[3944],QWd[3945],QWd[3946]}
function bb.controlSpot(Etc,Ftc)
if not bb.killZone()then
return nil
end
local Gtc=fb.holds
if not Gtc(Etc.id)or V.toggleOf(Etc.id)then
return nil
end
local Htc,Itc,Jtc,Ktc=1,0,0,{}
for Ltc,Mtc in ipairs(bb.mine or{})do
local Ntc=Mtc._stats
local Otc=Ntc.id.Value
if Ntc:FindFirstChild(QWd[2049])and not V.isFarm(Otc)and not V.allyBuff(Otc)then
local Ptc,Qtc=U.flat(Mtc:GetPivot().Position),Ntc.range.Value
if Gtc(Otc)and not V.toggleOf(Otc)then
Jtc=Jtc+1
table.insert(Ktc,{p=Ptc,r=Qtc})
else
for Rtc,Stc in ipairs(bb.samples)do
if(U.flat(Stc.pos)-Ptc).Magnitude<=Qtc then
Htc,Itc=math.min(Htc,Stc.prog),math.max(Itc,Stc.prog)
end
end
end
end
end
if Itc<=Htc then
Htc,Itc=0.75,0.98
end
local Ttc=(Ftc or Jtc)+1
local Utc=({Htc,Itc,(Htc+Itc)/2,Htc-(Itc-Htc)/2})[Ttc]
if not Utc then
return nil
end
local Vtc=V.range(Etc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Wtc={}
for Xtc,Ytc in ipairs(bb.cands)do
local Ztc,_tc,auc=U.flat(Ytc),0,0
for buc,cuc in ipairs(bb.samples)do
if(U.flat(cuc.pos)-Ztc).Magnitude<=Vtc then
auc=auc+1
if math.abs(cuc.prog-Utc)<=0.05 then
_tc=_tc+1
local duc=U.flat(cuc.pos)
for euc,fuc in ipairs(Ktc)do
if(duc-fuc.p).Magnitude<=fuc.r then
_tc=_tc-0.5
break
end
end
end
end
end
if _tc>0 then
table.insert(Wtc,{pos=Ytc,sc=_tc,cov=auc})
end
if Xtc%60==0 then
task.wait()
end
end
table.sort(Wtc,function(guc,huc)
return guc.sc>huc.sc
end)
for iuc,juc in ipairs(Wtc)do
local kuc=bb.valid(juc.pos,Etc.data)
if kuc then
F.log(1,QWd[3868],string.format(QWd[3947],V.name(Etc.id),bb.CONTROL_WORDS[Ttc],math.floor(Utc*100+0.5)))
return kuc,juc.cov,Utc
end
if iuc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(luc)
local muc,nuc=fb.holds(luc.id)
if not muc then
return nil
end
local ouc,puc={},0
for quc,ruc in ipairs(bb.mine or{})do
local suc=ruc._stats
local tuc=suc.id.Value
if suc:FindFirstChild(QWd[2049])and not V.isFarm(tuc)and not V.allyBuff(tuc)and tuc~=luc.id then
local uuc,vuc=pcall(bb.liveDps,ruc,tuc)
vuc=uuc and tonumber(vuc)or 0
if vuc>0 then
table.insert(ouc,{p=U.flat(ruc:GetPivot().Position),r=suc.range.Value,d=vuc})
puc=puc+vuc
end
end
end
if#ouc==0 or puc<=0 then
return nil
end
local wuc={}
for xuc,yuc in ipairs(bb.samples)do
local zuc,Auc=U.flat(yuc.pos),0
for Buc,Cuc in ipairs(ouc)do
if(zuc-Cuc.p).Magnitude<=Cuc.r then
Auc=Auc+Cuc.d
end
end
wuc[xuc]=Auc/puc
end
local Duc=V.range(luc.u,math.min(tonumber(nuc)or 0,3,V.rows(luc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Euc,Fuc,Guc
for Huc,Iuc in ipairs(bb.cands)do
local Juc,Kuc,Luc=U.flat(Iuc),0,0
for Muc,Nuc in ipairs(bb.samples)do
if(U.flat(Nuc.pos)-Juc).Magnitude<=Duc then
Kuc=Kuc+wuc[Muc]
Luc=Luc+1
end
end
if Kuc>0 and(not Fuc or Kuc>Fuc)then
local Ouc=bb.valid(Iuc,luc.data)
if Ouc then
Euc,Fuc,Guc=Ouc,Kuc,Luc
end
end
if Huc%40==0 then
task.wait()
end
end
if not Euc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[luc.id]then
