if P.caps[Oxc.uuid]~=Zxc or not V.learnedCap(Oxc.uuid)then
P.caps[Oxc.uuid],P.capsAt[Oxc.uuid]=Zxc,os.time()
F.log(1,QWd[3868],string.format(QWd[3958],V.name(Oxc.id),Zxc))
end
end
elseif bb.unitRefusals[Oxc.uuid]>=3 and(bb.noSpot[Oxc.uuid]or 0)<3 then
bb.noSpot[Oxc.uuid]=3
F.log(1,QWd[3868],string.format(QWd[3959],V.name(Oxc.id)))
end
if bb.refusals>=bb.REFUSE_FREE then
if not bb.placePause then
F.log(1,QWd[3868],string.format(QWd[3960],bb.refusals,bb.REFUSE_PAUSE))
end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,QWd[3868],QWd[3961]..Xxc..QWd[2683]..V.name(Oxc.id))
F.saveSoon()
end
return false
end
