end
local fBc=fb.cal(bb.key)
fBc.n=(tonumber(fBc.n)or 0)+1
local gBc=math.max(0.2,1/fBc.n)
local function hBc(iBc)
if#iBc==0 then
return nil
end
table.sort(iBc)
return iBc[math.ceil(#iBc/2)]
end
local function jBc(kBc,lBc)
if lBc then
fBc[kBc]=fBc[kBc]and(fBc[kBc]+(lBc-fBc[kBc])*gBc)or lBc
end
end
bb.hpRun=hBc(eBc.hp)
