local oBc=fb.mapWalk(nBc)
P.maps[nBc]=P.maps[nBc]or{}
local pBc=P.maps[nBc]
pBc.walkN=(tonumber(pBc.walkN)or 0)+1
pBc.walk=oBc and(oBc+(mBc-oBc)*math.max(0.2,1/(pBc.walkN+1)))or mBc
fb._walk[nBc]=pBc.walk
end
end
if(eBc.potSum or 0)>0 and(eBc.dealtSum or 0)>0 then
jBc(QWd[3977],U.clamp(eBc.dealtSum/eBc.potSum,0.1,2))
