local yBc=tonumber(uBc[wBc])
uBc[wBc]=yBc and(yBc+(xBc-yBc)*math.max(0.2,1/vBc))or xBc
end
P.maps[qBc].dens,P.maps[qBc].densN=uBc,vBc
end
if#eBc.pay>=2 then
jBc(QWd[3978],U.clamp(hBc(eBc.pay),0.5,2))
end
if not bb.joinedMid then
jBc(QWd[3979],hBc(eBc.waveSec))
jBc(QWd[3980],hBc(eBc.baseRel))
fBc.baseDps=nil
