jBc(QWd[3983],hBc(EBc))
jBc(QWd[3984],FBc[1]and U.clamp(hBc(FBc),0.2,6)or nil)
fBc.voteWave=type(fBc.voteWave)==QWd[1805]and fBc.voteWave or{}
