function bb.buffGain(zCc)
local ACc=V.allyBuff(zCc.id)
if not ACc then
return 0
end
local BCc=bb.buffShort(ACc)
local CCc=P.stack[ACc.attack]
local DCc=CCc and CCc.stacks and(CCc.cap or 1)or nil
local ECc,FCc=pcall(V.range,zCc.u,0)
FCc=(ECc and tonumber(FCc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local GCc=DCc and O.community and tonumber(ACc.time)and tonumber(ACc.cd)
local function HCc(ICc,JCc)
local KCc=math.floor(ICc*ACc.time/math.max(1,ACc.cd)+0.001)
return math.min(DCc,(1+JCc)^KCc-1)
end
local LCc=0
for MCc,NCc in ipairs(BCc)do
local OCc=0
for PCc,QCc in ipairs(BCc)do
if(QCc.pos-NCc.pos).Magnitude<=FCc then
local RCc=ACc.types[QCc.base]
local SCc=RCc*ACc.uptime
if GCc then
local TCc,UCc=HCc(QCc.n,RCc),QCc.n+1
while UCc<QCc.n+6 and HCc(UCc,RCc)<=TCc+0.001 do
