end
if iLc==QWd[3595]or iLc==QWd[3600]or iLc==QWd[3596]then
if kLc==QWd[2216]then
return math.max(0.3,1+jLc),0
end
if kLc==QWd[2049]then
return math.max(0.5,1+jLc/2),0
end
if kLc:find(QWd[2538])then
