function bb.learn()
local nLc=bb.calRun and bb.calRun.potBy
if type(nLc)~=QWd[1805]then
return
end
pcall(bb.sampleHelpers,true)
local oLc={}
for pLc,qLc in pairs(bb.ownDealt or{})do
if not V.isFarm(qLc.id)then
oLc[qLc.id]=(oLc[qLc.id]or 0)+(tonumber(qLc.v)or 0)
end
end
for rLc,sLc in pairs(bb.helperDealt or{})do
if sLc.owner and V.SUMMONER[sLc.owner]then
oLc[sLc.owner]=(oLc[sLc.owner]or 0)+(tonumber(sLc.v)or 0)
end
end
local tLc,uLc=0,0
for vLc,wLc in pairs(nLc)do
if wLc>0 then
tLc=tLc+(oLc[vLc]or 0)
uLc=uLc+wLc
end
end
if tLc<=0 or uLc<=0 then
return
end
local xLc=tLc/uLc
bb.lastEff={}
for yLc,zLc in pairs(nLc)do
if zLc>0 and zLc/uLc>0.02 then
local ALc=P.learn[yLc]or{eff=1,n=0,v=3}
if(tonumber(ALc.v)or 0)<3 then
ALc.eff,ALc.v=(tonumber(ALc.eff)or 1)*V.effRescale(yLc),3
end
local BLc=math.max(0.02,0.25*math.sqrt(30/(30+ALc.n)))
local CLc=U.clamp(((oLc[yLc]or 0)/zLc)/xLc,0.2,6)
bb.lastEff[yLc]=math.floor(CLc*1000+0.5)/1000
ALc.eff=ALc.eff+(CLc-ALc.eff)*BLc
ALc.n=ALc.n+1
P.learn[yLc]=ALc
end
end
local DLc=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if DLc and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==QWd[1805]and P.mapLearn or{}
local ELc=type(P.mapLearn[DLc])==QWd[1805]and P.mapLearn[DLc]or{}
for FLc,GLc in pairs(bb.lastEff)do
local HLc=type(ELc[FLc])==QWd[1805]and ELc[FLc]or{eff=GLc,n=0}
local ILc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(HLc.n)or 0))))
HLc.eff=(tonumber(HLc.n)or 0)==0 and GLc or((tonumber(HLc.eff)or GLc)+(GLc-(tonumber(HLc.eff)or GLc))*ILc)
HLc.n=(tonumber(HLc.n)or 0)+1
ELc[FLc]=HLc
end
ELc._at=os.time()
P.mapLearn[DLc]=ELc
if U.count(P.mapLearn)>80 then
local JLc,KLc
for LLc,MLc in pairs(P.mapLearn)do
if not KLc or(tonumber(MLc._at)or 0)<KLc then
JLc,KLc=LLc,tonumber(MLc._at)or 0
end
end
P.mapLearn[JLc]=nil
end
end
end
function bb.randomTeam()
