bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(rRc,sRc)
local tRc=(sRc.t or 0)-(rRc.t or 0)
if tRc<bb.BASE_WIN-1 then
return false
end
local uRc=((tonumber(rRc.base)or 0)-(tonumber(sRc.base)or 0))/tRc
if uRc<=0 or(tonumber(sRc.base)or 0)<=0 then
return false
end
local vRc=sRc.base/uRc
local wRc,xRc=0,0
local yRc,zRc=rRc.foes or{},sRc.foes or{}
for ARc,BRc in pairs(zRc)do
if BRc.prog>=bb.BASE_END then
wRc=wRc+BRc.hp
local CRc=yRc[ARc]
if CRc then
xRc=xRc+math.max(0,CRc.hp-BRc.hp)
end
end
end
for DRc,ERc in pairs(yRc)do
if ERc.prog>=bb.BASE_END and not zRc[DRc]then
xRc=xRc+ERc.hp
end
end
if wRc<=0 then
return false
end
local FRc=xRc/tRc
local GRc=FRc>0 and wRc/FRc or math.huge
local HRc={baseTime=vRc,loss=uRc,atEnd=wRc,rate=FRc,killTime=GRc}
return vRc<bb.BASE_SOON and GRc>vRc*bb.BASE_MARGIN,HRc
end
