if bb.kind==QWd[1825]and not bb.bailed and O.bailOut~=false and(wTc==0 or LTc<15)and rTc.net and LTc>4 and LTc<60 and(tonumber(P.dg.bails[NTc])or 0)<bb.BAIL_MAX then
local OTc=mTc.m and mTc.m:FindFirstChildOfClass(QWd[2178])
