local function aSd(bSd)
local cSd={}
for dSd,eSd in ipairs(type(bSd)==QWd[1805]and bSd or{})do
table.insert(cSd,tostring(eSd))
end
table.sort(cSd)
return table.concat(cSd,QWd[2745])
end
local fSd=aSd(VRd.ids)
