return 0,0,false
end
local gSd=mb.slog
local hSd=tostring(URd)..tostring(VRd.at)..tostring(type(VRd.result)==QWd[1805])
if not gSd or gSd.stamp~=hSd or U.now()-gSd.at>120 then
local iSd,jSd=0,0
local lSd,mSd=pcall(function()
local kSd=N.FOLDER..QWd[2285]..fb.SEARCH_LOG
return isfile(kSd)and readfile(kSd)or QWd[729]
end)
for nSd in(lSd and mSd or QWd[729]):gmatch(QWd[2580])do
if nSd:find(tostring(URd),1,true)then
local oSd=U.unjson(nSd)
if type(oSd)==QWd[1805]and oSd.key==URd and type(oSd.result)==QWd[1805]and aSd(oSd.picked)==fSd then
if oSd.result.won then
iSd=iSd+1
else
jSd=jSd+1
end
end
end
end
gSd={stamp=hSd,at=U.now(),w=iSd,l=jSd}
mb.slog=gSd
end
return gSd.w,gSd.l,false
end
function mb.whyWords(pSd)
local qSd,rSd,sSd,tSd,uSd,vSd,wSd={},{},{},{},0,{},{}
for xSd,ySd in ipairs(pSd.why or{})do
ySd=tostring(ySd)
local zSd,ASd=ySd:match(QWd[4983])
if zSd and ASd then
local BSd=zSd:gsub(QWd[6050],QWd[729])
local CSd=ASd:match(QWd[6051])
if CSd then
table.insert(qSd,string.format(QWd[3632],CSd,BSd))
end
if ASd:find(QWd[3516],1,true)then
table.insert(rSd,BSd)
end
local DSd,ESd=ASd:match(QWd[6052])
if DSd then
table.insert(sSd,string.format(QWd[6053],BSd,ESd,DSd,ESd==QWd[2219]and QWd[729]or QWd[1653]))
end
if ASd:find(QWd[6054],1,true)then
table.insert(tSd,BSd..QWd[6055])
end
if ASd:find(QWd[3523],1,true)then
uSd=uSd+1
end
if ASd:find(QWd[6056],1,true)then
table.insert(vSd,BSd..QWd[6057])
end
table.insert(wSd,QWd[4680]..zSd..QWd[2134]..ASd:gsub(QWd[3528],QWd[6058]))
end
end
local FSd={}
if#qSd>0 then
table.insert(FSd,QWd[6059]..table.concat(qSd,QWd[1916]))
end
if#rSd>0 then
table.insert(FSd,table.concat(rSd,QWd[2345])..(#rSd==1 and QWd[6060]or QWd[6061]))
end
for GSd,HSd in ipairs(sSd)do
table.insert(FSd,HSd)
end
for ISd,JSd in ipairs(tSd)do
table.insert(FSd,JSd)
end
local KSd=false
for LSd,MSd in ipairs(pSd.against or{})do
if tostring(MSd):find(QWd[3488],1,true)then
KSd=true
end
end
if KSd and uSd>0 then
table.insert(FSd,string.format(QWd[6062],uSd,uSd==1 and QWd[729]or QWd[1653]))
end
for NSd,OSd in ipairs(vSd)do
table.insert(FSd,OSd)
end
while#FSd>2 do
table.remove(FSd)
end
return FSd,wSd
end
function mb.recActive(PSd)
local QSd,RSd={},0
local SSd=(F.where==QWd[1876]and bb.team)or V.equipped()
for TSd,USd in ipairs(SSd or{})do
local VSd=V.name(USd.id)
QSd[VSd]=(QSd[VSd]or 0)+1
end
for WSd,XSd in ipairs(PSd.team or{})do
if not QSd[XSd]or QSd[XSd]<=0 then
return false
end
QSd[XSd]=QSd[XSd]-1
RSd=RSd+1
end
return RSd>0
end
function mb.recUuids(YSd,ZSd)
local _Sd=P.simTeam and P.simTeam[YSd]
if type(_Sd)==QWd[1805]and type(_Sd.uuids)==QWd[1805]and type(_Sd.names)==QWd[1805]and#_Sd.names== #(ZSd.team or{})then
local aTd={}
for bTd,cTd in ipairs(_Sd.names)do
aTd[cTd]=(aTd[cTd]or 0)+1
end
local dTd=true
for eTd,fTd in ipairs(ZSd.team or{})do
if not aTd[fTd]or aTd[fTd]<=0 then
dTd=false
else
aTd[fTd]=aTd[fTd]-1
end
end
if dTd then
return _Sd.uuids
end
end
local gTd=N.session()
if not gTd then
return nil
end
local hTd={}
for iTd,jTd in ipairs(V.equipped())do
hTd[jTd.uuid]=true
end
local kTd,lTd={},{}
for mTd,nTd in ipairs(ZSd.ids or{})do
local oTd,pTd
for qTd,rTd in pairs(gTd.profile_data.collection.owned_units)do
if rTd.unit_id==nTd and not lTd[qTd]then
local sTd=(hTd[qTd]and 1e12 or 0)+(tonumber(rTd.xp)or 0)
if not pTd or sTd>pTd then
oTd,pTd=qTd,sTd
end
end
end
if not oTd then
return nil
end
lTd[oTd]=true
table.insert(kTd,oTd)
end
return#kTd>0 and kTd or nil
end
