function mb.overviewView(lUd)
local mUd=mb.ov
if not mUd then
return
end
lUd=lUd or mb.COL
local nUd,oUd=pcall(mb.nowView,lUd)
if nUd and oUd then
pcall(mUd.now.Set,oUd)
pcall(function()
mb.Win:Status(oUd.status or oUd.title,oUd.statusColor)
end)
pcall(mb.K.barStatus,oUd.top)
end
local pUd,qUd=pcall(mb.predView,lUd)
if pUd and qUd then
pcall(mUd.sim.Set,qUd)
end
local rUd,sUd=pcall(mb.nextView,lUd)
if rUd and sUd then
pcall(mUd.next.Set,sUd)
end
local tUd,uUd=pcall(mb.lastView,lUd)
if tUd and uUd then
pcall(mUd.last.Set,uUd)
end
if ab.every(QWd[6104],2)then
local vUd,wUd=pcall(mb.searchView,lUd)
if not vUd and ab.every(QWd[6105],60)then
F.log(1,QWd[2169],QWd[6106]..tostring(wUd))
end
end
if ab.every(QWd[6107],2)then
pcall(mb.glanceView)
end
if mUd.parts and ab.every(QWd[6108],3)then
local xUd,yUd=pcall(mb.homeRows)
for zUd,AUd in ipairs(mb.HOME_KEYS)do
local BUd=xUd and yUd[AUd]or QWd[2645]
pcall(mUd.parts.Set,AUd,mb.cap(BUd),tostring(BUd):sub(1,3)==QWd[732]and lUd.sub or lUd.text,mb.HOME_LABELS[AUd]or mb.K.sentence(AUd))
